#include <algorithm>
#include <array>
#include <iostream>

int main() {
    std::array<int, 3> coins{10, 5, 1};
    int amount = 28;
    int count = 0;
    for (int coin : coins) { count += amount / coin; amount %= coin; }
    std::cout << "coins=" << count << ", remainder=" << amount << '\n';
}
